-- Round four of the decision form, as a migration rather than a script.
--
-- The first three rounds were seeded by hand, which meant somebody had to run
-- a command against production every time a form was written. Render already
-- runs db:migrate in its build command, before the app starts — that is how
-- 0021 added four destinations with nobody touching anything. A decision round
-- is rows in two tables and had no business being different.
--
-- Twelve questions, ordered by how much each unblocks. Every one of them is
-- something that has kept a change request open.

INSERT INTO decision_rounds (slug, title, lede)
VALUES ('close-out-2026-09', 'რაც ღია მოთხოვნებს აკლია',
        'ცხრა მოთხოვნა ღიაა. არა იმიტომ, რომ სამუშაო დგას — მხოლოდ დღეს ხუთი პუნქტი დაიხურა — არამედ იმიტომ, რომ 4 სექტემბრის თითოეული მოთხოვნა ათ-თხუთმეტპუნქტიანი დავალებაა და დარჩენილი სამ ჯგუფად იყოფა: ტექსტი, რომელსაც მხოლოდ თქვენ დაწერთ; მონაცემი, რომელიც სისტემას ჯერ არ აქვს; და ადგილები, სადაც თქვენივე ორი მითითება საპირისპიროდ მიდის. თითოეულ ბარათზე წერია, რა მდგომარეობაშია საქმე დღეს. უპასუხეთ მხოლოდ იმას, რაც თქვენ გეხებათ.')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO decision_questions (round_id, position, ticket, item, title, ask, stands, refs, need, options)
SELECT id, 10, 'CR-2026-0036', 'მთავარი კითხვა', '80 ადგილიდან ნაწილი სანახაობაა და არა მიმართულება — გავყოთ?', 'სად გინდა წასვლა — ეგ ჩამონათვალი უნდა განვავრცოთ… რეგიონების მიხედვით გამოყავი ადგილები',
       ARRAY['სიაში დაახლოებით 80 ადგილია; დღეს საიტს 23 აქვს. სამივე ენაზე თითო წინადადება და კოორდინატები სჭირდება თითოეულს — დაახლოებით 180 წინადადება.', 'სიის მესამედი არ არის ადგილი, სადაც მიდიხარ და ჩერდები: სვეტიცხოველი ტაძარია მცხეთაში, უშბა მთაა, რომელსაც უყურებ, გერგეტის სამება ყაზბეგშია. თითოეულისთვის ცალკე გვერდი სათაურით „როგორ ჩახვიდე და რა ღირს“ არასწორი იქნება.', 'თუ გავყოფთ, ერთი ნაბიჯით მეორე პუნქტიც იხურება: CR-2026-0010-ის მე-14 პუნქტი ითხოვს „მთავარ სანახაობებს“ ყველა მიმართულების გვერდზე, და დღეს ეს იმიტომ არ არსებობს, რომ ასეთი მონაცემი არსად გვქონდა. თქვენი ეს სია სწორედ ის მონაცემია.']::text[],
       ARRAY['src/lib/destinations.ts', 'CR-2026-0010 პუნქტი 14']::text[],
       'ერთი არჩევანი. ამაზეა დამოკიდებული, 60 გვერდი შეიქმნება თუ 40 გვერდი და 20 სანახაობა მათ შიგნით.',
       '[{"v":"split","label":"გავყოთ: მიმართულებები ცალკე, სანახაობები მათ შიგნით","why":"მცხეთის გვერდზე სვეტიცხოველი და ჯვარი „მთავარ სანახაობებში“ ჩნდება. ორ მოთხოვნას ერთად ხურავს."},{"v":"flat","label":"ერთი ბრტყელი სია, როგორც დაწერილია","why":"ყველაფერი ცალკე გვერდია, სვეტიცხოველიც. სწრაფია, მაგრამ 20-მდე გვერდი დაჯავშნას ვერ შესთავაზებს."},{"v":"later","label":"ჯერ მხოლოდ ნამდვილი მიმართულებები, სანახაობები მოგვიანებით","why":"ნახევარი სამუშაო ახლა, ნახევარი მაშინ, როცა ტექსტები მზად იქნება."}]'::jsonb
